<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
$role=$_SESSION['role']??'';$uid=(int)($_SESSION['user_id']??0);
if(!in_array($role,['system_admin','sub_admin','admin'],true)){http_response_code(403);exit('Your role cannot view school profiles.');}
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Choose a school.');}
$db=db();$sql='SELECT s.*,creator.name created_by_name,(SELECT u.name FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=s.id AND m.scope=\'manager\' AND u.role=\'director\' ORDER BY m.created_at LIMIT 1) director FROM schools s LEFT JOIN users creator ON creator.id=s.created_by WHERE s.id=?';$params=[$id];
if($role==='admin'){$sql.=' AND EXISTS(SELECT 1 FROM school_memberships m WHERE m.school_id=s.id AND m.user_id=?)';$params[]=$uid;}
$q=$db->prepare($sql);$q->execute($params);$school=$q->fetch();if(!$school){http_response_code(404);exit('School not found in your access.');}
$q=$db->prepare('SELECT c.id,c.name,(SELECT COUNT(*) FROM pupils p WHERE p.school_id=c.school_id AND p.class_level=c.name AND p.status=\'active\') pupil_count,(SELECT COUNT(*) FROM school_streams st WHERE st.class_id=c.id) stream_count,(SELECT COUNT(*) FROM school_class_subjects sj WHERE sj.class_id=c.id) subject_count FROM school_classes c WHERE c.school_id=? ORDER BY c.name');$q->execute([$id]);$classes=$q->fetchAll();
$q=$db->prepare('SELECT COUNT(*) FROM pupils WHERE school_id=? AND status=\'active\'');$q->execute([$id]);$pupils=(int)$q->fetchColumn();
$q=$db->prepare('SELECT COUNT(DISTINCT a.user_id) FROM teacher_assignments a WHERE a.school_id=? AND a.active=1');$q->execute([$id]);$teachers=(int)$q->fetchColumn();
$q=$db->prepare('SELECT COUNT(*) FROM school_exams WHERE school_id=?');$q->execute([$id]);$exams=(int)$q->fetchColumn();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($school['name'])?> · School profile</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="workspace-label">WORKSPACE</div><nav class="side-nav" aria-label="Main navigation"><a class="nav-item" href="index.php">⌂ &nbsp;Overview</a><a class="nav-item active" href="schools.php">▦ &nbsp;Schools</a><a class="nav-item" href="team.php">♧ &nbsp;People</a></nav><div class="sidebar-bottom"><a class="nav-item" href="logout.php">↪ &nbsp;Sign out</a></div></aside><main class="main-area"><header class="topbar"><div class="crumb">Workspace <span>/</span><a href="schools.php">Schools</a><span>/</span>View</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e($_SESSION['name']??'')?></div></div></header><div class="page-content"><section class="setup-hero"><div><div class="eyebrow">SCHOOL PROFILE</div><h1><?=e($school['name'])?></h1><p class="muted"><?=e($school['location']?:'Location not recorded')?></p></div><div class="academic-row-actions"><a class="button" href="school_analyze.php?id=<?=$id?>">Analyze</a><a class="button" href="schools.php">Back to schools</a></div></section><section class="metric-grid"><article class="metric-card"><div class="metric-label">ACTIVE PUPILS</div><div class="metric-value"><?=number_format($pupils)?></div><div class="metric-note">Currently enrolled</div></article><article class="metric-card"><div class="metric-label">CLASSES</div><div class="metric-value"><?=count($classes)?></div><div class="metric-note">Registered class levels</div></article><article class="metric-card"><div class="metric-label">TEACHERS</div><div class="metric-value"><?=number_format($teachers)?></div><div class="metric-note">With active teaching assignments</div></article><article class="metric-card"><div class="metric-label">EXAMS</div><div class="metric-value"><?=$exams?></div><div class="metric-note">Created assessment records</div></article></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">SCHOOL DETAILS</div><h2>Overview</h2></div></div><div class="table-wrap"><table><tbody><tr><th>Director</th><td><?=e($school['director']?:'—')?></td></tr><tr><th>Status</th><td><?=e(ucfirst($school['status']))?></td></tr><tr><th>Created by</th><td><?=e($school['created_by_name']?:'Deleted account')?></td></tr><tr><th>Created on</th><td><?=e(date('j M Y',strtotime($school['created_at'])))?></td></tr></tbody></table></div></section><section class="content-section"><div class="section-heading"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h2>Classes</h2></div><span class="count-pill"><?=count($classes)?> classes</span></div><?php if($classes):?><div class="table-wrap"><table><thead><tr><th>Class</th><th>Active pupils</th><th>Streams</th><th>Subjects</th></tr></thead><tbody><?php foreach($classes as $class):?><tr><th><?=e($class['name'])?></th><td><?=number_format((int)$class['pupil_count'])?></td><td><?=number_format((int)$class['stream_count'])?></td><td><?=number_format((int)$class['subject_count'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No classes registered</h3><p>This school has not added its class structure yet.</p></div><?php endif;?></section></div></main></div></body></html>
